const payload = $input.first().json.body ?? $input.first().json;
const booking = payload.payload ?? payload;

const uid         = booking.uid ?? booking.bookingId ?? '';
const startTime   = booking.startTime ?? '';
const propertyKey = (booking.type ?? '').toLowerCase().trim();

const attendees     = booking.attendees ?? [];
const primary       = attendees[0] ?? {};
const attendeeEmail = primary.email ?? booking.responses?.email?.value ?? '';
const attendeeName  = primary.name  ?? booking.responses?.name?.value  ?? '';

const meta      = booking.metadata ?? {};
const personId  = String(meta.fub_person_id ?? '');
const metaPhone = meta.phone ?? '';
const formPhone = booking.responses?.attendeePhoneNumber?.value
  ?? booking.responses?.phone?.value ?? '';
const attendeePhone = metaPhone || formPhone;

if (!uid)         throw new Error('Cal.com booking UID missing');
if (!propertyKey) throw new Error('Cal.com event type missing');
if (!startTime)   throw new Error('Cal.com startTime missing');

return [{ json: { uid, startTime, propertyKey, attendeeEmail, attendeeName, attendeePhone, personId } }];

const booking   = $('Parse Created Booking').first().json;
const allRows   = $input.all().map(i => i.json);
const propKey   = booking.propertyKey;

const prop = allRows.find(r => (r.property_key ?? '').trim() === propKey.trim());
if (!prop) throw new Error(`Property not found for key: ${propKey}`);

const lockId = String(prop.populife_lock_id ?? '').trim();
if (!lockId) throw new Error(`No Populife lock ID on property ${propKey} — assign a lockbox first`);

return [{ json: {
  propertyKey:     prop.property_key,
  propertyAddress: prop.street_address ?? propKey,
  populifeLockId:  lockId,
} }];

const booking  = $('Parse Created Booking').first().json;
const prop     = $('Find Property').first().json;
const fubResp  = $('FUB - Search by Phone').first().json;

const fubPerson = (fubResp.people ?? [])[0] ?? {};
const personId  = booking.personId || (fubPerson.id ? String(fubPerson.id) : '');

const fubPhone = (fubPerson.phones ?? [])[0]?.value ?? '';
const rawPhone = booking.attendeePhone || fubPhone;
const digits   = rawPhone.replace(/\D/g, '');
const phone    = digits.length === 10 ? `+1${digits}` : digits ? `+${digits}` : '';

const now = new Date();
const showingTime = new Date(booking.startTime);
const isImmediate = (showingTime - now) < 60 * 60 * 1000;

const row = {
  booking_uid:      booking.uid,
  property_key:     prop.propertyKey,
  property_address: prop.propertyAddress,
  person_id:        personId,
  person_name:      booking.attendeeName,
  person_email:     booking.attendeeEmail,
  person_phone:     phone,
  showing_time:     booking.startTime,
  status:           'scheduled',
  populife_lock_id: prop.populifeLockId,
  access_code:      '',
  access_code_id:   '',
  code_sent_at:     '',
  created_at:       now.toISOString(),
  updated_at:       now.toISOString(),
};

return [{ json: { ...row, isImmediate, personId, populifeLockId: prop.populifeLockId } }];

function calcWindow(showingTimeISO, availableBeforeMinutes) {
  const dt = new Date(showingTimeISO);
  const pad = n => String(n).padStart(2, '0');

  // Shift start back by available_before_minutes, then floor to hour
  const effectiveStart = new Date(dt.getTime() - availableBeforeMinutes * 60 * 1000);
  const startUtc = new Date(effectiveStart);
  startUtc.setUTCMinutes(0, 0, 0);

  // End is always the showing's own hour + 1
  const showingFloor = new Date(dt);
  showingFloor.setUTCMinutes(0, 0, 0);
  const endUtc = new Date(showingFloor.getTime() + 3600 * 1000);

  const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:00`;
  return { startDate: fmt(startUtc), endDate: fmt(endUtc), tzOffset: '0' };
}

const row = $('Build Showing Row').first().json;
const settings = {};
$('Read Settings (Code Gen)').all().forEach(i => {
  if (i.json.key && i.json.value) settings[i.json.key] = i.json.value;
});

const appKey    = settings.populife_app_key ?? '';
const appSecret = settings.populife_app_secret ?? '';
if (!appKey || !appSecret) throw new Error('Populife credentials missing from Settings sheet');

const availableBeforeMinutes = parseInt(settings.available_before_minutes || '0');
const { startDate, endDate, tzOffset } = calcWindow(row.showing_time, availableBeforeMinutes);

return [{ json: {
  ...row,
  appKey, appSecret,
  startDate, endDate, tzOffset,
  populifeLockId: row.populifeLockId,
} }];

function fmtShowingSlot(showingTimeISO) {
  const start = new Date(showingTimeISO);
  const end   = new Date(start.getTime() + 15 * 60 * 1000);
  const timeFmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', hour12: true
  });
  const dateFmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York', month: 'short', day: 'numeric', year: 'numeric'
  });
  return 'Valid from ' + timeFmt.format(start) + ' through ' + timeFmt.format(end) + ', ' + dateFmt.format(start);
}

function fmtTime(iso) {
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      weekday: 'short', month: 'short', day: 'numeric',
      hour: 'numeric', minute: '2-digit', hour12: true
    }).format(new Date(iso));
  } catch(e) { return iso; }
}

const row      = $('Build Showing Row').first().json;
const codeData = $('Populife - Generate Code (Created)').first().json;
const settings = {};
$('Read Settings (Code Gen)').all().forEach(i => {
  if (i.json.key && i.json.value) settings[i.json.key] = i.json.value;
});

const code       = codeData.data?.keyboardPwd ?? '';
const codeId     = String(codeData.data?.keyboardPwdId ?? '');
const template   = settings.access_code_sms_template ?? 'Your access code for {{address}} is: {{code}}';
const fromNumber = settings.from_number ?? '';

const validWindow = fmtShowingSlot(row.showing_time);
const windowNode  = $('Calc Code Window (Created)').first().json;

const message = template
  .replace('{{first_name}}',   row.person_name?.split(' ')[0] ?? '')
  .replace('{{name}}',         row.person_name ?? '')
  .replace('{{address}}',      row.property_address ?? row.property_key ?? '')
  .replace('{{date}}',         fmtTime(row.showing_time))
  .replace('{{code}}',         code)
  .replace('{{valid_window}}', validWindow)
  .replace('{{start}}',        windowNode.startDate ?? '')
  .replace('{{end}}',          windowNode.endDate ?? '');

return [{ json: {
  ...row,
  code, codeId, message,
  from_number: fromNumber,
  phone: row.person_phone,
  sent_at: new Date().toISOString(),
} }];

const payload = $input.first().json.body ?? $input.first().json;
const booking = payload.payload ?? payload;

const originalUid = booking.rescheduleUid ?? booking.uid ?? '';
const newUid      = booking.uid ?? '';
const startTime   = booking.startTime ?? '';
const attendee    = (booking.attendees ?? [])[0] ?? {};
const phone       = attendee.phoneNumber ?? '';

if (!originalUid) throw new Error('Rescheduled booking UID missing');
if (!startTime)   throw new Error('Rescheduled booking startTime missing');

return [{ json: { uid: originalUid, newUid, newStartTime: startTime, phone } }];

const parse = $('Parse Reschedule').first().json;
const originalUid = parse.uid;
const newUid      = parse.newUid;
const phone       = String(parse.phone ?? '').replace(/\D/g, '');

const rows = $input.all().map(i => i.json);

// Normalize phone helper
const norm = p => String(p ?? '').replace(/\D/g, '');

// 1. Try match by originalUid (rescheduleUid)
let row = rows.find(r => r.booking_uid === originalUid);

// 2. Try newUid (in case previous update already changed it)
if (!row) row = rows.find(r => r.booking_uid === newUid);

// 3. Fallback: match by phone + active status (scheduled/code_sent)
if (!row && phone) {
  row = rows.find(r =>
    norm(r.person_phone) === phone &&
    (r.status === 'scheduled' || r.status === 'code_sent')
  );
}

if (!row) return [{ json: { skipped: true, uid: originalUid } }];

return [{ json: {
  uid: originalUid,
  rowIndex:         Number(row.row_number),
  access_code_id:   row.access_code_id ?? '',
  populifeLockId:   row.populife_lock_id ?? '',
  property_key:     row.property_key ?? '',
  person_id:        row.person_id ?? '',
  person_name:      row.person_name ?? '',
  person_phone:     row.person_phone ?? '',
  property_address: row.property_address ?? '',
  found: true,
  matchedBookingUid: row.booking_uid,
} }];

